  async function openActiveSpellEditor(){const data=await reference('spells'),spells=data.records.slice().sort((a,b)=>a.name.localeCompare(b.name));if(!spells.length)throw new Error('The local spell catalogue is unavailable.');const first=spells[0];openEditor('Magic Effect','Add Magic Effect',`<div class="form-grid"><label class="wide">Spell<select id="activeSpellName" name="name">${spells.map(s=>`<option value="${esc(s.name)}">${esc(s.name)} — Level ${s.level||0}</option>`).join('')}</select></label>${field('Cast By','cast_by','','text','placeholder="Character, ally, creature, or item"')}<label>Cast Level<select id="activeSpellLevel" name="cast_level"></select></label>${field('Turns Remaining','turns_remaining',10,'number','min="0"')}<label class="check"><input id="activeSpellConcentration" name="concentration" type="checkbox"> Concentration</label><label>AC Bonus<input name="ac" type="number" value="0"></label><label>Saving Throw Bonus<input name="saving_throws" type="number" value="0"></label><label>Speed Bonus<input name="speed" type="number" value="0"></label><label>Attack Bonus<input name="attack" type="number" value="0"></label><label>Damage Bonus<input name="damage" type="number" value="0"></label><p id="activeSpellHelp" class="muted wide"></p></div>`,'Add Magic Effect',async form=>{const record=spells.find(s=>s.name===form.name)||first,castLevel=Number(form.cast_level||record.level||0),effects=Object.fromEntries(['ac','saving_throws','speed','attack','damage'].map(key=>[key,Number(form[key]||0)]).filter(([,value])=>value!==0));if(/^aid$/i.test(record.name)){const amount=5*Math.max(1,castLevel-1);effects.max_hp=amount;state.character.max_hp+=amount;state.character.current_hp+=amount;}state.character.active_spells.push({id:E.uid(),name:record.name,cast_by:form.cast_by.trim()||'External caster',cast_level:castLevel,turns_remaining:Number(form.turns_remaining||0),concentration:form.concentration==='on',effects,description:record.description||'',duration:record.duration||'',active:true});addCombatLog(`${record.name} added at level ${castLevel}, cast by ${form.cast_by||'External caster'}.`,'magic');await save('Added magic effect',false);refreshCharacter();});const select=$('activeSpellName'),level=$('activeSpellLevel'),concentration=$('activeSpellConcentration'),help=$('activeSpellHelp');const sync=()=>{const spell=spells.find(s=>s.name===select.value)||first,min=Number(spell.level||0),max=Math.max(min,9);level.innerHTML=Array.from({length:max-min+1},(_,i)=>min+i).map(x=>`<option>${x}</option>`).join('');concentration.checked=/concentration/i.test(spell.duration||'');help.textContent=`${spell.duration||'Duration not listed'} · ${spell.description||''}`;};select.onchange=sync;sync();}
  async function castSpell(name){const s=spellRecord(name),level=Number(s.level||0);if(!level){toast(`Cast ${name}. Cantrips do not use a slot.`);return;}const available=Object.keys(state.character.spell_slots_max||{}).filter(k=>Number(k)>=level&&(state.character.spell_slots_used[k]||0)<state.character.spell_slots_max[k]);if(!available.length)throw new Error(`No spell slot of level ${level} or higher remains.`);openEditor('Cast Spell',name,`<label>Slot Level<select name="level">${available.map(x=>`<option>${x}</option>`).join('')}</select></label>`,'Cast',async data=>{state.character.spell_slots_used[data.level]=(state.character.spell_slots_used[data.level]||0)+1;const duration=String(s.duration||'');if(duration&&!/instant/i.test(duration)){let turns=10,m=duration.match(/(\d+)\s*minute/i),r=duration.match(/(\d+)\s*round/i);if(m)turns=Number(m[1])*10;else if(r)turns=Number(r[1]);state.character.active_spells.push({id:E.uid(),name,cast_level:data.level,turns_remaining:turns,concentration:/concentration/i.test(duration),effects:{},description:s.description||''});}await save(`Cast ${name}`);refreshCharacter();});}
  async function loadFeatCatalogue(){try{const data=await reference('feats');$('featCatalogue').innerHTML=table(['Feat','Prerequisite','Description',''],data.records.slice(0,250).map(f=>[esc(f.name),esc(f.prerequisite||'—'),esc(f.description||'—'),`<button class="text-button" data-add-feat="${esc(f.name)}">Add</button>`]));document.querySelectorAll('[data-add-feat]').forEach(b=>b.onclick=()=>addFeat(data.records.find(f=>f.name===b.dataset.addFeat)));}catch(e){$('featCatalogue').textContent=e.message;}}
